  1	// Pure billing rules (brief section 3). No imports, no I/O, and no use of the
  2	// machine's timezone: calendar dates are handled as (year, month, day)
  3	// integers and serial day numbers, and "today in Malaysia" is derived from
  4	// the instant's epoch milliseconds plus a fixed UTC+8 offset.
  5	
  6	const MS_PER_DAY = 86_400_000;
  7	const MALAYSIA_OFFSET_MS = 8 * 60 * 60 * 1000; // Asia/Kuala_Lumpur: UTC+8, no DST
  8	const ISO_DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
  9	const RINGGIT_PATTERN =
 10	  /^([0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)(?:\.([0-9]{1,2}))?$/;
 11	
 12	export type InvoiceKind = "deposit" | "rent";
 13	
 14	export interface ScheduledInvoice {
 15	  kind: InvoiceKind;
 16	  periodIndex: number | null; // 0, 1, 2... for rent; null for the deposit
 17	  periodStart: string | null; // 'YYYY-MM-DD'; null for the deposit
 18	  periodEnd: string | null; // 'YYYY-MM-DD', inclusive; null for the deposit
 19	  dueDate: string; // 'YYYY-MM-DD'
 20	  amountSen: number; // integer
 21	}
 22	
 23	export type InvoiceStatus = "paid" | "partially_paid" | "unpaid" | "overdue";
 24	
 25	type CalendarDate = { year: number; month: number; day: number };
 26	
 27	type LeaseTerms = {
 28	  startDate: string;
 29	  endDate: string;
 30	  monthlyRentSen: number;
 31	  depositSen: number;
 32	};
 33	
 34	type InvoiceAmounts = { dueDate: string; amountSen: number; paidSen: number };
 35	
 36	const isLeapYear = (year: number): boolean =>
 37	  (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
 38	
 39	const daysInMonth = (year: number, month: number): number => {
 40	  if (month === 2) {
 41	    return isLeapYear(year) ? 29 : 28;
 42	  }
 43	  return [4, 6, 9, 11].includes(month) ? 30 : 31;
 44	};
 45	
 46	const parseCalendarDate = (value: unknown, field: string): CalendarDate => {
 47	  const match = typeof value === "string" ? ISO_DATE_PATTERN.exec(value) : null;
 48	  if (!match) {
 49	    throw new Error(`${field} must be a date written as YYYY-MM-DD`);
 50	  }
 51	  const year = Number(match[1]);
 52	  const month = Number(match[2]);
 53	  const day = Number(match[3]);
 54	  if (
 55	    year < 1 ||
 56	    month < 1 ||
 57	    month > 12 ||
 58	    day < 1 ||
 59	    day > daysInMonth(year, month)
 60	  ) {
 61	    throw new Error(`${field} is not a real calendar date: ${String(value)}`);
 62	  }
 63	  return { year, month, day };
 64	};
 65	
 66	// Serial day number (days since 1970-01-01) of a proleptic Gregorian date.
 67	// Howard Hinnant's days_from_civil: exact integer arithmetic, no Date object.
 68	const toDayNumber = ({ year, month, day }: CalendarDate): number => {
 69	  const y = month <= 2 ? year - 1 : year;
 70	  const era = Math.floor(y / 400);
 71	  const yearOfEra = y - era * 400;
 72	  const dayOfYear =
 73	    Math.floor((153 * (month + (month > 2 ? -3 : 9)) + 2) / 5) + day - 1;
 74	  const dayOfEra =
 75	    yearOfEra * 365 +
 76	    Math.floor(yearOfEra / 4) -
 77	    Math.floor(yearOfEra / 100) +
 78	    dayOfYear;
 79	  return era * 146_097 + dayOfEra - 719_468;
 80	};
 81	
 82	// Inverse of toDayNumber (Hinnant's civil_from_days).
 83	const fromDayNumber = (dayNumber: number): CalendarDate => {
 84	  const z = dayNumber + 719_468;
 85	  const era = Math.floor(z / 146_097);
 86	  const dayOfEra = z - era * 146_097;
 87	  const yearOfEra = Math.floor(
 88	    (dayOfEra -
 89	      Math.floor(dayOfEra / 1460) +
 90	      Math.floor(dayOfEra / 36_524) -
 91	      Math.floor(dayOfEra / 146_096)) /
 92	      365,
 93	  );
 94	  const dayOfYear =
 95	    dayOfEra -
 96	    (365 * yearOfEra + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100));
 97	  const mp = Math.floor((5 * dayOfYear + 2) / 153);
 98	  const day = dayOfYear - Math.floor((153 * mp + 2) / 5) + 1;
 99	  const month = mp < 10 ? mp + 3 : mp - 9;
100	  const year = yearOfEra + era * 400 + (month <= 2 ? 1 : 0);
101	  return { year, month, day };
102	};
103	
104	const formatCalendarDate = ({ year, month, day }: CalendarDate): string =>
105	  `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
106	
107	// Start date plus k calendar months, day clamped to the target month's length.
108	// Always counted from the start date, so Jan 31 -> Feb 28 -> Mar 31 (not Mar 28).
109	const addMonthsClamped = (
110	  start: CalendarDate,
111	  months: number,
112	): CalendarDate => {
113	  const monthIndex = start.month - 1 + months;
114	  const year = start.year + Math.floor(monthIndex / 12);
115	  const month = (monthIndex % 12) + 1;
116	  return { year, month, day: Math.min(start.day, daysInMonth(year, month)) };
117	};
118	
119	// monthlyRent * used / full, rounded half up, in exact integer arithmetic:
120	// floor((2 * rent * used + full) / (2 * full)). BigInt so no float ever appears.
121	const prorateHalfUp = (
122	  monthlyRentSen: number,
123	  daysUsed: number,
124	  daysInFullPeriod: number,
125	): number => {
126	  const numerator =
127	    2n * BigInt(monthlyRentSen) * BigInt(daysUsed) + BigInt(daysInFullPeriod);
128	  return Number(numerator / (2n * BigInt(daysInFullPeriod)));
129	};
130	
131	const assertSafeInteger = (
132	  value: unknown,
133	  field: string,
134	  minimum: number,
135	): number => {
136	  if (
137	    typeof value !== "number" ||
138	    !Number.isSafeInteger(value) ||
139	    value < minimum
140	  ) {
141	    throw new Error(
142	      `${field} must be an integer >= ${minimum}, got ${String(value)}`,
143	    );
144	  }
145	  return value;
146	};
147	
148	export const isCalendarDate = (value: unknown): value is string => {
149	  try {
150	    parseCalendarDate(value, "date");
151	    return true;
152	  } catch {
153	    return false;
154	  }
155	};
156	
157	// The calendar date in Malaysia (UTC+8, no DST) at a given instant, 'YYYY-MM-DD'.
158	export const malaysiaDateOf = (now: Date): string => {
159	  const time = now instanceof Date ? now.getTime() : Number.NaN;
160	  if (!Number.isFinite(time)) {
161	    throw new Error("now must be a valid Date");
162	  }
163	  return formatCalendarDate(
164	    fromDayNumber(Math.floor((time + MALAYSIA_OFFSET_MS) / MS_PER_DAY)),
165	  );
166	};
167	
168	export const generateSchedule = (lease: LeaseTerms): ScheduledInvoice[] => {
169	  const start = parseCalendarDate(lease.startDate, "startDate");
170	  const end = parseCalendarDate(lease.endDate, "endDate");
171	  const monthlyRentSen = assertSafeInteger(
172	    lease.monthlyRentSen,
173	    "monthlyRentSen",
174	    1,
175	  );
176	  const depositSen = assertSafeInteger(lease.depositSen, "depositSen", 0);
177	  const startDay = toDayNumber(start);
178	  const endDay = toDayNumber(end);
179	  if (endDay < startDay) {
180	    throw new Error("endDate must not be before startDate");
181	  }
182	
183	  const schedule: ScheduledInvoice[] = [];
184	  if (depositSen > 0) {
185	    schedule.push({
186	      kind: "deposit",
187	      periodIndex: null,
188	      periodStart: null,
189	      periodEnd: null,
190	      dueDate: lease.startDate,
191	      amountSen: depositSen,
192	    });
193	  }
194	
195	  for (let k = 0; ; k++) {
196	    const anchor = addMonthsClamped(start, k);
197	    const anchorDay = toDayNumber(anchor);
198	    if (anchorDay > endDay) {
199	      break;
200	    }
201	    const nextAnchorDay = toDayNumber(addMonthsClamped(start, k + 1));
202	    const fullEndDay = nextAnchorDay - 1;
203	    const periodEndDay = Math.min(fullEndDay, endDay);
204	    const amountSen =
205	      periodEndDay < fullEndDay
206	        ? prorateHalfUp(
207	            monthlyRentSen,
208	            periodEndDay - anchorDay + 1,
209	            nextAnchorDay - anchorDay,
210	          )
211	        : monthlyRentSen;
212	    const periodStart = formatCalendarDate(anchor);
213	    schedule.push({
214	      kind: "rent",
215	      periodIndex: k,
216	      periodStart,
217	      periodEnd: formatCalendarDate(fromDayNumber(periodEndDay)),
218	      dueDate: periodStart,
219	      amountSen,
220	    });
221	  }
222	  return schedule;
223	};
224	
225	export const invoiceStatus = (
226	  invoice: InvoiceAmounts,
227	  now: Date,
228	): InvoiceStatus => {
229	  const due = parseCalendarDate(invoice.dueDate, "dueDate");
230	  const amountSen = assertSafeInteger(invoice.amountSen, "amountSen", 0);
231	  const paidSen = assertSafeInteger(invoice.paidSen, "paidSen", 0);
232	  const today = parseCalendarDate(malaysiaDateOf(now), "today");
233	  if (paidSen >= amountSen) {
234	    return "paid";
235	  }
236	  if (toDayNumber(today) > toDayNumber(due)) {
237	    return "overdue";
238	  }
239	  if (paidSen > 0) {
240	    return "partially_paid";
241	  }
242	  return "unpaid";
243	};
244	
245	export const parseRinggitToSen = (input: string): number => {
246	  const match =
247	    typeof input === "string" ? RINGGIT_PATTERN.exec(input.trim()) : null;
248	  if (!match || match[1] === undefined) {
249	    throw new Error(`Not a valid ringgit amount: ${JSON.stringify(input)}`);
250	  }
251	  // Built from the digit strings, never via parseFloat: "1.15" must be 115, not 114.99...
252	  const ringgit = BigInt(match[1].replaceAll(",", ""));
253	  const sen = BigInt((match[2] ?? "").padEnd(2, "0"));
254	  const total = ringgit * 100n + sen;
255	  if (total > BigInt(Number.MAX_SAFE_INTEGER)) {
256	    throw new Error(`Amount is too large: ${JSON.stringify(input)}`);
257	  }
258	  return Number(total);
259	};

