    34	// "amountSen: Invalid input: expected number" — names the first failing field,
    35	// never echoes the submitted value.
    36	const describeZodError = (error: z.ZodError): string => {
    37	  const issue = error.issues[0];
    38	  if (!issue) {
    39	    return "Invalid input";
    40	  }
    41	  const path = issue.path.map(String).join(".");
    42	  return path ? `${path}: ${issue.message}` : issue.message;
    43	};
    44	
    45	// Wraps a route handler. Generic over the context so routes keep Next's typing,
    46	// e.g. handle<RouteContext<"/api/leases/[leaseId]">>(async (req, ctx) => …).
    47	export const handle =
    48	  <C = unknown>(fn: RouteFn<C>): RouteFn<C> =>
    49	  async (req, ctx) => {
    50	    try {
    51	      return await fn(req, ctx);
    52	    } catch (error) {
    53	      // Let Next's own control-flow errors (redirect, notFound, …) through.
    54	      unstable_rethrow(error);
    55	      if (error instanceof HttpError) {
    56	        return jsonError(error.status, error.message);
    57	      }
    58	      if (error instanceof z.ZodError) {
    59	        return jsonError(400, describeZodError(error));
    60	      }
    61	      // Message only: never log request bodies, tokens or the gateway key.
    62	      console.error(
    63	        "Unhandled route error:",
    64	        error instanceof Error ? error.message : "non-Error thrown",
    65	      );
    66	      return jsonError(500, "Internal error");
    67	    }
    68	  };
