    70	export const readJson = async <T>(
    71	  req: Request,
    72	  schema: z.ZodType<T>,
    73	): Promise<T> => {
    74	  let body: unknown;
    75	  try {
    76	    body = await req.json();
    77	  } catch {
    78	    throw badRequest("Invalid JSON body");
    79	  }
    80	  const result = schema.safeParse(body);
    81	  if (!result.success) {
    82	    throw badRequest(describeZodError(result.error));
    83	  }
    84	  return result.data;
    85	};
