    87	// Reads a JSON body WITHOUT validating it, for routes whose service must run
    88	// its 404/403 checks before input validation (401 → 404 → 403 → 400). Invalid
    89	// JSON becomes `undefined`, which the service's zod schema rejects with 400.
    90	export const readJsonBody = async (req: Request): Promise<unknown> => {
    91	  try {
    92	    return await req.json();
    93	  } catch {
