     1	import "server-only";
     2	
     3	// Prisma 7 with @prisma/adapter-pg wraps Postgres errors several layers deep
     4	// (PrismaClientKnownRequestError -> meta.driverAdapterError -> cause, with the
     5	// SQLSTATE in `originalCode` or, for unmapped codes like 23P01, `code`).
     6	// This walks the chain and returns the first SQLSTATE found, so services can
     7	// map constraint and trigger errors to HTTP statuses.
     8	
     9	// Five-character SQLSTATE; Prisma's own codes (P1000–P6999) are excluded, while
    10	// Postgres' PL/pgSQL class P0 (P0001 raise_exception) is kept.
    11	const SQLSTATE_PATTERN = /^(?!P[1-9])[0-9A-Z]{5}$/;
    12	const MAX_DEPTH = 6;
    13	
    14	const isRecord = (value: unknown): value is Record<string, unknown> =>
    15	  typeof value === "object" && value !== null;
    16	
    17	const findSqlState = (value: unknown, depth: number): string | null => {
    18	  if (!isRecord(value) || depth > MAX_DEPTH) {
    19	    return null;
    20	  }
    21	  for (const key of ["originalCode", "code"]) {
    22	    const code = value[key];
    23	    if (typeof code === "string" && SQLSTATE_PATTERN.test(code)) {
    24	      return code;
    25	    }
    26	  }
    27	  for (const key of ["cause", "meta", "driverAdapterError"]) {
    28	    const found = findSqlState(value[key], depth + 1);
    29	    if (found) {
    30	      return found;
    31	    }
    32	  }
    33	  return null;
    34	};
    35	
    36	/** The Postgres SQLSTATE behind a Prisma error ('23P01', '23505', …), or null. */
    37	export const pgErrorCode = (error: unknown): string | null =>
    38	  findSqlState(error, 0);
