145	const scheduleOrBadRequest = (
146	  input: z.output<typeof createLeaseSchema>,
147	): ScheduledInvoice[] => {
148	  let schedule: ScheduledInvoice[];
149	  try {
150	    schedule = generateSchedule(input);
151	  } catch (error) {
152	    throw badRequest(error instanceof Error ? error.message : "Invalid lease");
153	  }
154	  if (schedule.length > MAX_SCHEDULE_LENGTH) {
