160	/**
161	 * Manager only. Stores the lease and exactly generateSchedule's invoices, all
162	 * or nothing. Overlap safety: the unit row is locked first, so concurrent
163	 * creates on one unit queue up and the pre-check sees the earlier lease; the
164	 * leases_no_overlap exclusion constraint is the backstop (23P01 -> 409).
165	 */
166	export const createLease = async (
167	  actor: Actor,
168	  input: unknown,
169	): Promise<{ id: string }> => {
170	  requireManager(actor);
171	  const data = createLeaseSchema.parse(input);
172	  const schedule = scheduleOrBadRequest(data);
173	  // IDs in the body are untrusted: another org's unit/tenant is "not found".
174	  if (!isUuid(data.unitId) || !isUuid(data.tenantId)) {
175	    throw notFound();
176	  }
177	  const startDate = calendarDateToDb(data.startDate);
178	  const endDate = calendarDateToDb(data.endDate);
179	
180	  try {
181	    return await prisma.$transaction(async (tx) => {
182	      const units = await tx.$queryRaw<{ id: string }[]>`
183	        SELECT id FROM public.units
184	         WHERE id = ${data.unitId}::uuid AND org_id = ${actor.orgId}::uuid
185	           FOR UPDATE`;
186	      if (units.length === 0) {
187	        throw notFound();
188	      }
189	      const tenant = await tx.tenants.findFirst({
190	        where: { id: data.tenantId, org_id: actor.orgId },
191	        select: { id: true },
192	      });
193	      if (!tenant) {
194	        throw notFound();
195	      }
196	      // Both ends inclusive: [a, b] and [c, d] overlap iff a <= d and c <= b.
197	      const overlapping = await tx.leases.findFirst({
198	        where: {
199	          unit_id: data.unitId,
200	          start_date: { lte: endDate },
201	          end_date: { gte: startDate },
202	        },
203	        select: { id: true },
204	      });
205	      if (overlapping) {
206	        throw conflict(OVERLAP_MESSAGE);
207	      }
208	
209	      const lease = await tx.leases.create({
210	        data: {
211	          org_id: actor.orgId,
212	          unit_id: data.unitId,
213	          tenant_id: data.tenantId,
214	          start_date: startDate,
215	          end_date: endDate,
216	          monthly_rent_sen: BigInt(data.monthlyRentSen),
217	          deposit_sen: BigInt(data.depositSen),
218	          created_by: actor.userId,
219	        },
220	        select: { id: true },
221	      });
222	      await tx.invoices.createMany({
223	        data: schedule.map((invoice): Prisma.invoicesCreateManyInput => ({
224	          org_id: actor.orgId,
225	          lease_id: lease.id,
226	          kind: invoice.kind,
227	          period_index: invoice.periodIndex,
228	          period_start:
229	            invoice.periodStart === null
230	              ? null
231	              : calendarDateToDb(invoice.periodStart),
232	          period_end:
233	            invoice.periodEnd === null
234	              ? null
235	              : calendarDateToDb(invoice.periodEnd),
236	          due_date: calendarDateToDb(invoice.dueDate),
237	          amount_sen: BigInt(invoice.amountSen),
238	        })),
239	      });
240	      await writeAudit(tx, {
241	        orgId: actor.orgId,
242	        actorId: actor.userId,
243	        action: "lease.created",
244	        entityId: lease.id,
245	        details: {
246	          unitId: data.unitId,
247	          tenantId: data.tenantId,
248	          startDate: data.startDate,
249	          endDate: data.endDate,
250	          monthlyRentSen: data.monthlyRentSen,
251	          depositSen: data.depositSen,
252	          invoiceCount: schedule.length,
253	        },
254	      });
255	      return { id: lease.id };
256	    }, TRANSACTION_OPTIONS);
257	  } catch (error) {
258	    if (pgErrorCode(error) === EXCLUSION_VIOLATION) {
259	      throw conflict(OVERLAP_MESSAGE);
260	    }
261	    throw error;
262	  }
263	};
