265	/**
266	 * GET /api/leases/:leaseId. Invoices in allocation order (due date, deposit
267	 * before rent, period index); paid = sum of allocations; status computed now.
268	 */
269	export const getLeaseDetail = async (
270	  actor: Actor,
271	  leaseId: string,
272	  now: Date = new Date(),
273	): Promise<LeaseDetail> => {
274	  const lease = await requireVisibleLease(actor, leaseId);
275	  const [invoices, payments] = await Promise.all([
276	    prisma.invoices.findMany({
277	      where: { lease_id: lease.id },
278	      // kind ASC puts 'deposit' before 'rent' (alphabetical), which is the
279	      // brief's "deposit before rent" tie-break on the same due date.
280	      orderBy: [{ due_date: "asc" }, { kind: "asc" }, { period_index: "asc" }],
281	      include: { payment_allocations: { select: { amount_sen: true } } },
282	    }),
283	    prisma.payments.findMany({
284	      where: { lease_id: lease.id },
285	      orderBy: [{ received_at: "asc" }, { created_at: "asc" }],
286	    }),
287	  ]);
288	
289	  return {
290	    lease: {
291	      id: lease.id,
292	      unitId: lease.unit_id,
293	      tenantId: lease.tenant_id,
294	      startDate: calendarDateFromDb(lease.start_date),
295	      endDate: calendarDateFromDb(lease.end_date),
296	      monthlyRentSen: toSafeNumber(lease.monthly_rent_sen),
297	      depositSen: toSafeNumber(lease.deposit_sen),
298	    },
299	    invoices: invoices.map((invoice) => {
300	      const paidSen = toSafeNumber(
301	        invoice.payment_allocations.reduce((sum, a) => sum + a.amount_sen, 0n),
302	      );
303	      const amountSen = toSafeNumber(invoice.amount_sen);
304	      const dueDate = calendarDateFromDb(invoice.due_date);
305	      return {
306	        id: invoice.id,
307	        kind: asInvoiceKind(invoice.kind),
308	        periodIndex: invoice.period_index,
309	        periodStart:
310	          invoice.period_start === null
311	            ? null
312	            : calendarDateFromDb(invoice.period_start),
313	        periodEnd:
314	          invoice.period_end === null
315	            ? null
316	            : calendarDateFromDb(invoice.period_end),
317	        dueDate,
318	        amountSen,
319	        paidSen,
320	        status: invoiceStatus({ dueDate, amountSen, paidSen }, now),
321	      };
322	    }),
323	    payments: payments.map((payment) => ({
324	      id: payment.id,
325	      amountSen: toSafeNumber(payment.amount_sen),
326	      unappliedSen: toSafeNumber(payment.unapplied_sen),
327	      method: asPaymentMethod(payment.method),
328	      status: asPaymentStatus(payment.status),
329	      receivedAt: toMalaysiaIso(payment.received_at),
330	    })),
331	  };
332	};
