389	/**
390	 * Dashboard numbers for staff and managers. The overdue count uses
391	 * invoiceStatus (statuses are never stored); SQL only pre-filters invoices
392	 * that are not fully paid and due before today's Malaysia date.
393	 */
394	export const dashboardStats = async (
395	  actor: Actor,
396	  now: Date = new Date(),
397	): Promise<DashboardStats> => {
398	  requireMember(actor);
399	  const today = todayInMalaysia(now);
400	  const candidates = await prisma.$queryRaw<OverdueCandidateRow[]>`
401	    SELECT i.due_date, i.amount_sen,
402	           coalesce(sum(a.amount_sen), 0)::bigint AS paid_sen
403	      FROM public.invoices i
404	      LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
405	     WHERE i.org_id = ${actor.orgId}::uuid
406	       AND i.due_date < ${today}::date
407	     GROUP BY i.id
408	    HAVING coalesce(sum(a.amount_sen), 0) < i.amount_sen`;
409	  const overdueCount = candidates.filter(
410	    (row) =>
411	      invoiceStatus(
412	        {
413	          dueDate: calendarDateFromDb(row.due_date),
414	          amountSen: toSafeNumber(BigInt(row.amount_sen)),
415	          paidSen: toSafeNumber(BigInt(row.paid_sen)),
416	        },
417	        now,
418	      ) === "overdue",
419	  ).length;
420	  return { overdueCount };
421	};
