3	import type { payments } from "@/generated/prisma/client";
4	import { toSafeNumber } from "@/lib/money";
5	import {
6	  requireManager,
7	  requireMember,
8	  requireVisibleLease,
9	  requireVisiblePayment,
10	} from "../access";
11	import {
12	  allocatePayment,
13	  leaseTotals,
14	  lockLease,
15	  writeAudit,
16	  type Tx,
17	} from "../allocation";
18	import type { Actor } from "../auth";
