24	// Manual payments (cash, bank transfer) and the manager decisions on them.
25	//
26	// Concurrency: every transaction here locks the lease row FIRST (lockLease),
27	// then re-reads whatever it decides on. Two staff recording at once, or two
28	// managers approving at once, therefore run one after the other on that
29	// lease, and the second sees the first's committed rows: the cap cannot be
30	// exceeded together and a payment cannot be approved (allocated) twice.
31	//
32	// Check order in every entry point: 404 (not visible) -> 403 (role) ->
33	// 400 (input) -> 409 (state) / 422 (amount). 401 is the route's job.
34	
35	const MAX_CLOCK_SKEW_MS = 5 * 60 * 1000;
36	const TRANSACTION_OPTIONS = { maxWait: 10000, timeout: 20000 };
37	const FK_VIOLATION = "23503";
38	const UNIQUE_VIOLATION = "23505";
39	
40	const recordPaymentSchema = z.object({
41	  amountSen: z.int().positive(),
42	  method: z.enum(["cash", "bank_transfer"]),
43	  // ISO 8601 with an explicit offset (Z or ±hh:mm); a bare local time is
44	  // ambiguous on a UTC server, so it is refused rather than guessed.
45	  receivedAt: z.union([z.iso.datetime({ offset: true }), z.date()]),
46	  slipPath: z.string().min(1).optional(),
47	});
48	
49	const reasonSchema = z.object({
50	  reason: z.string().trim().min(5, "Reason must be at least 5 characters"),
51	});
52	
53	export type RecordPaymentInput = z.input<typeof recordPaymentSchema>;
54	export type ReasonInput = z.input<typeof reasonSchema>;
55	export type PaymentStatus =
56	  "pending_verification" | "approved" | "rejected" | "voided";
57	export type RecordPaymentResult = { id: string; status: PaymentStatus };
58	export type DecisionResult = { status: PaymentStatus };
59	export type SlipInput = Omit<RecordPaymentInput, "slipPath" | "method"> & {
60	  method: "cash" | "bank_transfer";
61	};
62	
63	const toInstant = (value: string | Date): Date => {
64	  const instant = typeof value === "string" ? new Date(value) : value;
65	  if (Number.isNaN(instant.getTime())) {
66	    throw badRequest("receivedAt: Invalid date-time");
67	  }
68	  return instant;
69	};
