71	// Re-reads the payment under a row lock, after the lease lock is held.
72	const lockPayment = async (tx: Tx, paymentId: string): Promise<payments> => {
73	  await tx.$queryRaw`
74	    SELECT id FROM public.payments WHERE id = ${paymentId}::uuid FOR UPDATE`;
75	  const payment = await tx.payments.findUnique({ where: { id: paymentId } });
76	  if (!payment) {
77	    throw notFound();
78	  }
79	  return payment;
80	};
81	
82	const asStatus = (status: string): PaymentStatus => {
83	  if (
84	    status !== "pending_verification" &&
85	    status !== "approved" &&
86	    status !== "rejected" &&
87	    status !== "voided"
88	  ) {
89	    throw new Error(`Unknown payment status in database: ${status}`);
90	  }
91	  return status;
92	};
