222	/**
223	 * Manager only. Re-checks the amount against the remaining balance at this
224	 * moment (invoiced - allocated); if it no longer fits, 422 and it stays
225	 * pending. Approving twice at once: the second waits on the lease lock, then
226	 * sees 'approved' and gets 409, so allocation happens once.
227	 */
228	export const approvePayment = async (
229	  actor: Actor,
230	  paymentId: string,
231	): Promise<DecisionResult> => {
232	  const visible = await requireVisiblePayment(actor, paymentId);
233	  requireManager(actor);
234	  return prisma.$transaction(async (tx) => {
235	    await lockLease(tx, visible.lease_id);
236	    const payment = await lockPayment(tx, visible.id);
237	    if (payment.status !== "pending_verification") {
238	      throw conflict(`Payment is ${payment.status}, not pending_verification`);
239	    }
240	    const totals = await leaseTotals(tx, payment.lease_id);
241	    const remaining = totals.invoicedSen - totals.allocatedSen;
242	    if (payment.amount_sen > remaining) {
243	      throw unprocessable(
244	        `Amount exceeds the remaining balance (${remaining > 0n ? remaining.toString() : "0"} sen)`,
245	      );
246	    }
247	    await tx.payments.update({
248	      where: { id: payment.id },
249	      data: {
250	        status: "approved",
251	        decided_by: actor.userId,
252	        decided_at: new Date(),
253	      },
254	    });
255	    await allocatePayment(tx, payment.id);
256	    await writeAudit(tx, {
257	      orgId: payment.org_id,
258	      actorId: actor.userId,
259	      action: "payment.approved",
260	      entityId: payment.id,
261	      details: {
262	        leaseId: payment.lease_id,
263	        amountSen: toSafeNumber(payment.amount_sen),
264	      },
265	    });
266	    return { status: "approved" as const };
267	  }, TRANSACTION_OPTIONS);
