305	/**
306	 * Manager only. approved -> voided, with a reason; removes this payment's
307	 * allocations only. Other payments are not touched and nothing is
308	 * re-allocated (in particular, no other payment's unapplied_sen moves in to
309	 * fill the reopened invoices — see DECISIONS.md).
310	 */
311	export const voidPayment = async (
312	  actor: Actor,
313	  paymentId: string,
314	  input: unknown,
315	): Promise<DecisionResult> => {
316	  const visible = await requireVisiblePayment(actor, paymentId);
317	  requireManager(actor);
318	  const { reason } = reasonSchema.parse(input);
319	  return prisma.$transaction(async (tx) => {
320	    await lockLease(tx, visible.lease_id);
321	    const payment = await lockPayment(tx, visible.id);
322	    if (payment.status !== "approved") {
323	      throw conflict(`Payment is ${payment.status}, not approved`);
