96	 * payment is approved (and allocated) at once; a staff payment waits as
97	 * pending_verification. Capped at the lease's remaining balance minus what is
98	 * already pending.
99	 */
100	export const recordPayment = async (
101	  actor: Actor,
102	  leaseId: string,
103	  input: unknown,
104	  now: Date = new Date(),
105	): Promise<RecordPaymentResult> => {
106	  const lease = await requireVisibleLease(actor, leaseId);
107	  requireMember(actor);
108	  const data = recordPaymentSchema.parse(input);
109	  const receivedAt = toInstant(data.receivedAt);
110	  if (receivedAt.getTime() > now.getTime() + MAX_CLOCK_SKEW_MS) {
111	    throw badRequest("receivedAt cannot be in the future");
112	  }
113	  if (data.method === "bank_transfer") {
114	    if (!data.slipPath) {
115	      throw badRequest("slipPath: A bank transfer needs a slip");
116	    }
117	    if (!data.slipPath.startsWith(`${lease.org_id}/`)) {
118	      throw badRequest("slipPath: Slip must be in the organization's folder");
119	    }
120	  } else if (data.slipPath !== undefined) {
121	    throw badRequest("slipPath: Only a bank transfer has a slip");
122	  }
123	
124	  const approveNow = actor.role === "manager";
125	  try {
126	    return await prisma.$transaction(async (tx) => {
127	      await lockLease(tx, lease.id);
128	      const totals = await leaseTotals(tx, lease.id);
129	      const cap = totals.invoicedSen - totals.allocatedSen - totals.pendingSen;
130	      if (BigInt(data.amountSen) > cap) {
131	        throw unprocessable(
132	          `Amount exceeds the remaining balance (max ${cap > 0n ? cap.toString() : "0"} sen)`,
133	        );
134	      }
135	      const decidedAt = new Date();
136	      const payment = await tx.payments.create({
137	        data: {
138	          org_id: lease.org_id,
139	          lease_id: lease.id,
140	          amount_sen: BigInt(data.amountSen),
141	          method: data.method,
142	          status: approveNow ? "approved" : "pending_verification",
143	          received_at: receivedAt,
144	          slip_path: data.slipPath ?? null,
145	          recorded_by: actor.userId,
146	          decided_by: approveNow ? actor.userId : null,
147	          decided_at: approveNow ? decidedAt : null,
148	        },
149	        select: { id: true, status: true },
150	      });
151	      await writeAudit(tx, {
152	        orgId: lease.org_id,
153	        actorId: actor.userId,
154	        action: "payment.recorded",
155	        entityId: payment.id,
156	        details: {
157	          leaseId: lease.id,
158	          amountSen: data.amountSen,
159	          method: data.method,
160	          receivedAt: receivedAt.toISOString(),
161	          slipPath: data.slipPath ?? null,
162	        },
163	      });
164	      if (approveNow) {
165	        await allocatePayment(tx, payment.id);
166	        await writeAudit(tx, {
167	          orgId: lease.org_id,
168	          actorId: actor.userId,
169	          action: "payment.approved",
170	          entityId: payment.id,
171	          details: {
172	            leaseId: lease.id,
173	            amountSen: data.amountSen,
174	            onRecord: true,
175	          },
176	        });
177	      }
178	      return { id: payment.id, status: asStatus(payment.status) };
179	    }, TRANSACTION_OPTIONS);
180	  } catch (error) {
181	    const code = pgErrorCode(error);
182	    // payments_slip_exists trigger: the file is not in the bucket.
183	    if (code === FK_VIOLATION) {
184	      throw badRequest("slipPath: Slip file not found");
185	    }
186	    // payments.slip_path is unique: one slip backs one payment.
187	    if (code === UNIQUE_VIOLATION) {
188	      throw badRequest("slipPath: Slip is already used by another payment");
189	    }
190	    throw error;
191	  }
192	};
