654	   166	/** Inclusive list of 'YYYY-MM' months from `from` to `to`; throws if from > to. */
655	   167	export const monthsBetween = (from: string, to: string): string[] => {
656	   168	  const start = parseYearMonth(from);
657	   169	  const end = parseYearMonth(to);
658	   170	  const first = start.year * 12 + start.month - 1;
659	   171	  const last = end.year * 12 + end.month - 1;
660	   172	  if (first > last) {
661	   173	    throw new Error(`Month range is reversed: ${from} > ${to}`);
662	   174	  }
663	   175	  const months: string[] = [];
664	   176	  for (let index = first; index <= last; index++) {
665	   177	    months.push(formatYearMonth(Math.floor(index / 12), (index % 12) + 1));
666	   178	  }
667	   179	  return months;
668	   180	};
