670	   182	/** [from, to] covering the last n Malaysia calendar months, ending with the current one. */
671	   183	export const lastNMonths = (now: Date, n: number): [string, string] => {
672	   184	  if (!Number.isSafeInteger(n) || n < 1) {
673	   185	    throw new Error(`n must be a positive integer, got ${String(n)}`);
674	   186	  }
675	   187	  const { year, month } = parseYearMonth(malaysiaMonthOf(now));
676	   188	  const fromIndex = year * 12 + month - 1 - (n - 1);
677	   189	  return [
678	   190	    formatYearMonth(Math.floor(fromIndex / 12), (fromIndex % 12) + 1),
679	   191	    formatYearMonth(year, month),
680	   192	  ];
681	   193	};
