683	   195	/** Instant at which a Malaysia calendar month starts (00:00 on the 1st, UTC+8). */
684	   196	export const malaysiaMonthStart = (yearMonth: string): Date => {
685	   197	  parseYearMonth(yearMonth);
686	   198	  return malaysiaLocalToInstant(`${yearMonth}-01T00:00`);
687	   199	};
688	   200	
689	   201	/**
690	   202	 * Half-open instant range [start, endExclusive) covering Malaysia months
691	   203	 * from..to inclusive — the WHERE clause of the collections report.
692	   204	 */
693	   205	export const malaysiaMonthRange = (
694	   206	  from: string,
695	   207	  to: string,
696	   208	): { start: Date; endExclusive: Date } => {
697	   209	  monthsBetween(from, to); // validates both and rejects a reversed range
698	   210	  const { year, month } = parseYearMonth(to);
699	   211	  const next =
700	   212	    month === 12
701	   213	      ? formatYearMonth(year + 1, 1)
702	   214	      : formatYearMonth(year, month + 1);
703	   215	  return {
704	   216	    start: malaysiaMonthStart(from),
705	   217	    endExclusive: malaysiaMonthStart(next),
706	   218	  };
707	   219	};
