// TEMPORARY audit probe — delete after use.
vi.mock("next/headers", () => ({
  cookies: async () => ({ getAll: () => [], set: () => undefined }),
}));

const PW = "Rentals2026!";
const tokens: Record<string, string> = {};
const tok = async (email: string) => {
  if (tokens[email]) return tokens[email];
  const c = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL ?? "",
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY ?? "",
    { auth: { persistSession: false } },
  );
  const { data, error } = await c.auth.signInWithPassword({ email, password: PW });
  if (error || !data.session) throw new Error(`login ${email}: ${error?.message}`);
  tokens[email] = data.session.access_token;
  return tokens[email];
};

type Run = (req: Request, ctx: { params: Promise<Record<string, string>> }) => Promise<Response>;
const call = async (
  label: string,
  run: unknown,
  opts: { method?: string; path: string; email?: string; auth?: string; body?: unknown; params?: Record<string, string>; ct?: string },
) => {
  const headers = new Headers();
  if (opts.email) headers.set("authorization", `Bearer ${await tok(opts.email)}`);
  if (opts.auth) headers.set("authorization", opts.auth);
  let body: string | undefined;
  if (opts.body !== undefined) {
    headers.set("content-type", opts.ct ?? "application/json");
    body = typeof opts.body === "string" ? opts.body : JSON.stringify(opts.body);
  }
  const req = new Request(`http://localhost:3000${opts.path}`, { method: opts.method ?? "POST", headers, body });
  const res = await (run as Run)(req, { params: Promise.resolve(opts.params ?? {}) });
  const text = await res.text();
  console.log(`### ${label} -> ${res.status} ct=${res.headers.get("content-type")} ${text.slice(0, 1500)}`);
  return { status: res.status, text };
};

const KEY = process.env.GATEWAY_X_SIGNATURE_KEY ?? "";
const signed = (fields: Record<string, string>) => {
  const source = Object.keys(fields).sort().map((k) => `${k}${fields[k]}`).join("|");
  return new URLSearchParams({ ...fields, x_signature: createHmac("sha256", KEY).update(source).digest("hex") }).toString();
};
const hook = (label: string, body: string) =>
  call(label, webhookRoute, { path: "/api/webhooks/gateway", body, ct: "application/x-www-form-urlencoded" });

